    #[allow(unused_mut)]
    pub fn create<'bldr: 'args, 'args: 'mut_bldr, 'mut_bldr, A: ::flatbuffers::Allocator + 'bldr>(
        _fbb: &'mut_bldr mut ::flatbuffers::FlatBufferBuilder<'bldr, A>,
        args: &'args SRTArgs<'args>
    ) -> ::flatbuffers::WIPOffset<SRT<'bldr>> {
        let mut builder = SRTBuilder::new(_fbb);
        builder.add_DATA_COVERAGE_FRACTION(args.DATA_COVERAGE_FRACTION);
        builder.add_MAX_VALUE(args.MAX_VALUE);
        builder.add_MIN_VALUE(args.MIN_VALUE);
        builder.add_NORTH_DEG(args.NORTH_DEG);
        builder.add_EAST_DEG(args.EAST_DEG);
        builder.add_SOUTH_DEG(args.SOUTH_DEG);
        builder.add_WEST_DEG(args.WEST_DEG);
        builder.add_NO_DATA_VALUE(args.NO_DATA_VALUE);
        builder.add_ADD_OFFSET(args.ADD_OFFSET);
        builder.add_SCALE_FACTOR(args.SCALE_FACTOR);
        if let Some(x) = args.PROVENANCE { builder.add_PROVENANCE(x); }
        if let Some(x) = args.EPOCH { builder.add_EPOCH(x); }
        if let Some(x) = args.PAYLOAD { builder.add_PAYLOAD(x); }
        if let Some(x) = args.HORIZONTAL_DATUM_NAME { builder.add_HORIZONTAL_DATUM_NAME(x); }
        builder.add_Y(args.Y);
        builder.add_X(args.X);
        builder.add_LEVEL(args.LEVEL);
        builder.add_GRID_HEIGHT(args.GRID_HEIGHT);
        builder.add_GRID_WIDTH(args.GRID_WIDTH);
        if let Some(x) = args.AFFINE_TRANSFORM { builder.add_AFFINE_TRANSFORM(x); }
        if let Some(x) = args.CRS { builder.add_CRS(x); }
        if let Some(x) = args.CLASS_LEGEND { builder.add_CLASS_LEGEND(x); }
        if let Some(x) = args.UNIT { builder.add_UNIT(x); }
        if let Some(x) = args.QUANTITY_NAME { builder.add_QUANTITY_NAME(x); }
        if let Some(x) = args.TILESET_NAME { builder.add_TILESET_NAME(x); }
        if let Some(x) = args.TILESET_ID { builder.add_TILESET_ID(x); }
        builder.add_PAYLOAD_FORMAT(args.PAYLOAD_FORMAT);
        builder.add_TILING_SCHEME(args.TILING_SCHEME);
        builder.add_PIXEL_REGISTRATION(args.PIXEL_REGISTRATION);
        builder.add_SAMPLE_TYPE(args.SAMPLE_TYPE);
        builder.add_QUANTITY(args.QUANTITY);
        builder.finish()
    }

    pub fn unpack(&self) -> SRTT {
        let TILESET_ID = {
            let x = self.TILESET_ID();
            alloc::string::ToString::to_string(x)
        };
        let TILESET_NAME = self.TILESET_NAME().map(|x| {
            alloc::string::ToString::to_string(x)
        });
        let QUANTITY = self.QUANTITY();
        let QUANTITY_NAME = self.QUANTITY_NAME().map(|x| {
            alloc::string::ToString::to_string(x)
        });
        let UNIT = self.UNIT().map(|x| {
            alloc::string::ToString::to_string(x)
        });
        let SAMPLE_TYPE = self.SAMPLE_TYPE();
        let SCALE_FACTOR = self.SCALE_FACTOR();
        let ADD_OFFSET = self.ADD_OFFSET();
        let NO_DATA_VALUE = self.NO_DATA_VALUE();
        let CLASS_LEGEND = self.CLASS_LEGEND().map(|x| {
            x.iter().map(|t| t.unpack()).collect()
        });
        let CRS = {
            let x = self.CRS();
            alloc::string::ToString::to_string(x)
        };
        let AFFINE_TRANSFORM = self.AFFINE_TRANSFORM().map(|x| {
            x.into_iter().collect()
        });
        let PIXEL_REGISTRATION = self.PIXEL_REGISTRATION();
        let GRID_WIDTH = self.GRID_WIDTH();
        let GRID_HEIGHT = self.GRID_HEIGHT();
        let TILING_SCHEME = self.TILING_SCHEME();
        let LEVEL = self.LEVEL();
        let X = self.X();
        let Y = self.Y();
        let WEST_DEG = self.WEST_DEG();
        let SOUTH_DEG = self.SOUTH_DEG();
        let EAST_DEG = self.EAST_DEG();
        let NORTH_DEG = self.NORTH_DEG();
        let HORIZONTAL_DATUM_NAME = self.HORIZONTAL_DATUM_NAME().map(|x| {
            alloc::string::ToString::to_string(x)
        });
        let PAYLOAD_FORMAT = self.PAYLOAD_FORMAT();
        let PAYLOAD = {
            let x = self.PAYLOAD();
            alloc::boxed::Box::new(x.unpack())
        };
        let MIN_VALUE = self.MIN_VALUE();
        let MAX_VALUE = self.MAX_VALUE();
        let DATA_COVERAGE_FRACTION = self.DATA_COVERAGE_FRACTION();
        let EPOCH = self.EPOCH().map(|x| {
            alloc::string::ToString::to_string(x)
        });
        let PROVENANCE = {
            let x = self.PROVENANCE();
            alloc::boxed::Box::new(x.unpack())
        };
        SRTT {
            TILESET_ID,
            TILESET_NAME,
            QUANTITY,
            QUANTITY_NAME,
            UNIT,
            SAMPLE_TYPE,
            SCALE_FACTOR,
            ADD_OFFSET,
            NO_DATA_VALUE,
            CLASS_LEGEND,
            CRS,
            AFFINE_TRANSFORM,
            PIXEL_REGISTRATION,
            GRID_WIDTH,
            GRID_HEIGHT,
            TILING_SCHEME,
            LEVEL,
            X,
            Y,
            WEST_DEG,
            SOUTH_DEG,
            EAST_DEG,
            NORTH_DEG,
            HORIZONTAL_DATUM_NAME,
            PAYLOAD_FORMAT,
            PAYLOAD,
            MIN_VALUE,
            MAX_VALUE,
            DATA_COVERAGE_FRACTION,
            EPOCH,
            PROVENANCE,
        }
    }

