impl SRTT {
    pub fn pack<'b, A: ::flatbuffers::Allocator + 'b>(
        &self,
        _fbb: &mut ::flatbuffers::FlatBufferBuilder<'b, A>
    ) -> ::flatbuffers::WIPOffset<SRT<'b>> {
        let TILESET_ID = Some({
            let x = &self.TILESET_ID;
            _fbb.create_string(x)
        });
        let TILESET_NAME = self.TILESET_NAME.as_ref().map(|x|{
            _fbb.create_string(x)
        });
        let QUANTITY = self.QUANTITY;
        let QUANTITY_NAME = self.QUANTITY_NAME.as_ref().map(|x|{
            _fbb.create_string(x)
        });
        let UNIT = self.UNIT.as_ref().map(|x|{
            _fbb.create_string(x)
        });
        let SAMPLE_TYPE = self.SAMPLE_TYPE;
        let SCALE_FACTOR = self.SCALE_FACTOR;
        let ADD_OFFSET = self.ADD_OFFSET;
        let NO_DATA_VALUE = self.NO_DATA_VALUE;
        let CLASS_LEGEND = self.CLASS_LEGEND.as_ref().map(|x|{
            let w: alloc::vec::Vec<_> = x.iter().map(|t| t.pack(_fbb)).collect();_fbb.create_vector(&w)
        });
        let CRS = Some({
            let x = &self.CRS;
            _fbb.create_string(x)
        });
        let AFFINE_TRANSFORM = self.AFFINE_TRANSFORM.as_ref().map(|x|{
            _fbb.create_vector(x)
        });
        let PIXEL_REGISTRATION = self.PIXEL_REGISTRATION;
        let GRID_WIDTH = self.GRID_WIDTH;
        let GRID_HEIGHT = self.GRID_HEIGHT;
        let TILING_SCHEME = self.TILING_SCHEME;
        let LEVEL = self.LEVEL;
        let X = self.X;
        let Y = self.Y;
        let WEST_DEG = self.WEST_DEG;
        let SOUTH_DEG = self.SOUTH_DEG;
        let EAST_DEG = self.EAST_DEG;
        let NORTH_DEG = self.NORTH_DEG;
        let HORIZONTAL_DATUM_NAME = self.HORIZONTAL_DATUM_NAME.as_ref().map(|x|{
            _fbb.create_string(x)
        });
        let PAYLOAD_FORMAT = self.PAYLOAD_FORMAT;
        let PAYLOAD = Some({
            let x = &self.PAYLOAD;
            x.pack(_fbb)
        });
        let MIN_VALUE = self.MIN_VALUE;
        let MAX_VALUE = self.MAX_VALUE;
        let DATA_COVERAGE_FRACTION = self.DATA_COVERAGE_FRACTION;
        let EPOCH = self.EPOCH.as_ref().map(|x|{
            _fbb.create_string(x)
        });
        let PROVENANCE = Some({
            let x = &self.PROVENANCE;
            x.pack(_fbb)
        });
        SRT::create(_fbb, &SRTArgs{
            TILESET_ID,
            TILESET_NAME,
            QUANTITY,
            QUANTITY_NAME,
            UNIT,
            SAMPLE_TYPE,
            SCALE_FACTOR,
            ADD_OFFSET,
            NO_DATA_VALUE,
            CLASS_LEGEND,
            CRS,
            AFFINE_TRANSFORM,
            PIXEL_REGISTRATION,
            GRID_WIDTH,
            GRID_HEIGHT,
            TILING_SCHEME,
            LEVEL,
            X,
            Y,
            WEST_DEG,
            SOUTH_DEG,
            EAST_DEG,
            NORTH_DEG,
            HORIZONTAL_DATUM_NAME,
            PAYLOAD_FORMAT,
            PAYLOAD,
            MIN_VALUE,
            MAX_VALUE,
            DATA_COVERAGE_FRACTION,
            EPOCH,
            PROVENANCE,
        })
    }
}

/// Verifies that a buffer of bytes contains a `SRT`
/// and returns it.
/// Note that verification is still experimental and may not
/// catch every error, or be maximally performant. For the
/// previous, unchecked, behavior use
/// `root_as_srt_unchecked`.
#[inline]
pub fn root_as_srt(buf: &[u8]) -> Result<SRT<'_>, ::flatbuffers::InvalidFlatbuffer> {
    ::flatbuffers::root::<SRT>(buf)
}

/// Verifies that a buffer of bytes contains a size prefixed
/// `SRT` and returns it.
/// Note that verification is still experimental and may not
/// catch every error, or be maximally performant. For the
/// previous, unchecked, behavior use
/// `size_prefixed_root_as_srt_unchecked`.
#[inline]
pub fn size_prefixed_root_as_srt(buf: &[u8]) -> Result<SRT<'_>, ::flatbuffers::InvalidFlatbuffer> {
    ::flatbuffers::size_prefixed_root::<SRT>(buf)
}

/// Verifies, with the given options, that a buffer of bytes
/// contains a `SRT` and returns it.
/// Note that verification is still experimental and may not
/// catch every error, or be maximally performant. For the
/// previous, unchecked, behavior use
/// `root_as_srt_unchecked`.
#[inline]
pub fn root_as_srt_with_opts<'b, 'o>(
    opts: &'o ::flatbuffers::VerifierOptions,
    buf: &'b [u8],
) -> Result<SRT<'b>, ::flatbuffers::InvalidFlatbuffer> {
    ::flatbuffers::root_with_opts::<SRT<'b>>(opts, buf)
}

/// Verifies, with the given verifier options, that a buffer of
/// bytes contains a size prefixed `SRT` and returns
/// it. Note that verification is still experimental and may not
/// catch every error, or be maximally performant. For the
/// previous, unchecked, behavior use
/// `root_as_srt_unchecked`.
#[inline]
