pub unsafe fn size_prefixed_root_as_srt_unchecked(buf: &[u8]) -> SRT<'_> {
    unsafe { ::flatbuffers::size_prefixed_root_unchecked::<SRT>(buf) }
}

pub const SRT_IDENTIFIER: &str = "$SRT";

#[inline]
pub fn srt_buffer_has_identifier(buf: &[u8]) -> bool {
    ::flatbuffers::buffer_has_identifier(buf, SRT_IDENTIFIER, false)
}

#[inline]
pub fn srt_size_prefixed_buffer_has_identifier(buf: &[u8]) -> bool {
    ::flatbuffers::buffer_has_identifier(buf, SRT_IDENTIFIER, true)
}

#[inline]
pub fn finish_srt_buffer<'a, 'b, A: ::flatbuffers::Allocator + 'a>(
    fbb: &'b mut ::flatbuffers::FlatBufferBuilder<'a, A>,
    root: ::flatbuffers::WIPOffset<SRT<'a>>
) {
    fbb.finish(root, Some(SRT_IDENTIFIER));
}

#[inline]
pub fn finish_size_prefixed_srt_buffer<'a, 'b, A: ::flatbuffers::Allocator + 'a>(
    fbb: &'b mut ::flatbuffers::FlatBufferBuilder<'a, A>,
    root: ::flatbuffers::WIPOffset<SRT<'a>>
) {
    fbb.finish_size_prefixed(root, Some(SRT_IDENTIFIER));
}
